ALTER TABLE "rental_operations"."operational_blocks" ADD COLUMN "completed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "rental_operations"."operational_blocks" ADD COLUMN "completed_by_actor_id" text;--> statement-breakpoint
UPDATE "rental_operations"."operational_blocks" SET "completed_at"="updated_at", "completed_by_actor_id"='legacy-migration' WHERE "status"='RELEASED';--> statement-breakpoint
