ALTER TABLE "rental_operations"."operational_blocks" ADD CONSTRAINT "operational_blocks_completion_check" CHECK (("rental_operations"."operational_blocks"."status" = 'ACTIVE' AND "rental_operations"."operational_blocks"."completed_at" IS NULL AND "rental_operations"."operational_blocks"."completed_by_actor_id" IS NULL) OR ("rental_operations"."operational_blocks"."status" = 'RELEASED' AND "rental_operations"."operational_blocks"."completed_at" IS NOT NULL AND "rental_operations"."operational_blocks"."completed_by_actor_id" IS NOT NULL));
